router.delete("/agents/:id", async (req, res) => {
  assertBoard(req);
  const id = req.params.id as string;
  if (!(await getAccessibleAgent(req, res, id))) {
    return;
  }
  const agent = await svc.remove(id);
  if (!agent) {
    res.status(404).json({ error: "Agent not found" });
    return;
  }

  await logActivity(db, {
    companyId: agent.companyId,
    actorType: "user",
    actorId: req.actor.userId ?? "board",
    action: "agent.deleted",
    entityType: "agent",
    entityId: agent.id,
  });

  res.json({ ok: true });
});

router.get("/agents/:id/keys", async (req, res) => {
  assertBoard(req);
  const id = req.params.id as string;
  const agent = await getAccessibleAgent(req, res, id);
  if (!agent) {
    return;
  }
  const keys = await svc.listKeys(id);
  res.json(keys);
});

router.post("/agents/:id/keys", validate(createAgentKeySchema), async (req, res) => {
  assertBoard(req);
  const id = req.params.id as string;
  const agent = await getAccessibleAgent(req, res, id);
  if (!agent) {
    return;
  }
  const key = await svc.createApiKey(id, req.body.name);

  await logActivity(db, {
    companyId: agent.companyId,
    actorType: "user",
    actorId: req.actor.userId ?? "board",
    action: "agent.key_created",
    entityType: "agent",
    entityId: agent.id,
    details: { keyId: key.id, name: key.name },
  });

  res.status(201).json(key);
});

router.delete("/agents/:id/keys/:keyId", async (req, res) => {
  assertBoard(req);
  const id = req.params.id as string;
  const keyId = req.params.keyId as string;
  const agent = await getAccessibleAgent(req, res, id);
  if (!agent) {
    return;
  }

  const key = await svc.getKeyById(keyId);
  if (!key || key.agentId !== agent.id) {
    res.status(404).json({ error: "Key not found" });
    return;
  }

  const revoked = await svc.revokeKey(agent.id, keyId);
  if (!revoked) {
    res.status(404).json({ error: "Key not found" });
    return;
  }

  await logActivity(db, {
    companyId: agent.companyId,
    actorType: "user",
    actorId: req.actor.userId ?? "board",
    action: "agent.key_revoked",
    entityType: "agent",
    entityId: agent.id,
    details: { keyId: key.id, name: key.name },
  });

  res.json({ ok: true });
});

router.post("/agents/:id/wakeup", validate(wakeAgentSchema), async (req, res) => {
  const id = req.params.id as string;
  const agent = await svc.getById(id);
  if (!agent) {
    res.status(404).json({ error: "Agent not found" });
    return;
  }
  assertCompanyAccess(req, agent.companyId);

  if (req.actor.type === "agent") {
    if (req.actor.agentId !== id) {
      res.status(403).json({ error: "Agent can only invoke itself" });
      return;
    }
  } else {
    await assertBoardCanManageAgentsForCompany(req, agent.companyId);
  }

  const run = await heartbeat.wakeup(id, {
    source: req.body.source,
    triggerDetail: req.body.triggerDetail ?? "manual",
    reason: req.body.reason ?? null,
    payload: req.body.payload ?? null,
    idempotencyKey: req.body.idempotencyKey ?? null,
    requestedByActorType: req.actor.type === "agent" ? "agent" : "user",
    requestedByActorId: req.actor.type === "agent" ? req.actor.agentId ?? null : req.actor.userId ?? null,
    contextSnapshot: {
      triggeredBy: req.actor.type,
      actorId: req.actor.type === "agent" ? req.actor.agentId : req.actor.userId,
      forceFreshSession: req.body.forceFreshSession === true,
    },
  });

  if (!run) {
    res.status(202).json(await buildSkippedWakeupResponse(agent, req.body.payload ?? null));
    return;
  }

  const actor = getActorInfo(req);
  await logActivity(db, {
    companyId: agent.companyId,
    actorType: actor.actorType,
    actorId: actor.actorId,
    agentId: actor.agentId,
    runId: actor.runId,
    action: "heartbeat.invoked",
    entityType: "heartbeat_run",
    entityId: run.id,
    details: { agentId: id },
  });

  res.status(202).json(run);
});

